llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Lurtotecan has an absolute oral bioavailability of 11.3% ± 5.2 in patients, below the 20% threshold, supporting a low-F prediction for the query's polar polycyclic dicarboxylate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Dronedarone has an absolute oral bioavailability of only 4% in fasted humans, demonstrating that poor absorption and first-pass effects can drive F far below 20%; this supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Eliglustat's simulated absolute oral bioavailability is 8.6%, below the 20% threshold, providing additional support for low F in a molecule with challenging absorption properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "YH4808 has a low absolute oral bioavailability of 10.1% (range 2.3-19.3%), below the 20% threshold, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ofloxacin, a structurally related quinolone, has >95% absolute oral bioavailability, which would argue for high F; however, the query lacks the basic amine and has an additional ionizable carboxylate, so this high-F phenotype is not directly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C66"],
      "claim": "Pefloxacin is 100% bioavailable after oral dosing, but as an N-ethyl quinolone mono-acid with a basic piperazine it is much less polar than the query's dicarboxylate, limiting transfer of the high-F result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Norfloxacin has ~70% oral bioavailability, above the threshold, but its moderate absorption is enabled by a basic piperazine; the query's extra carboxylate and absent basic center predict greater polarity and lower absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a pyranoquinoline dicarboxylic acid (nedocromil-like) with two ionizable carboxylates and no basic center, expected to be very poorly absorbed orally. Multiple consistent low-F analogues (lurtotecan, dronedarone, eliglustat, YH4808) support F < 20%, while high-F quinolone evidence is weakened by key structural differences.",
  "evidence_gaps": [
    "No direct oral bioavailability record for the query molecule itself is present in the supplied evidence.",
    "The highest-transfer evidence (ofloxacin) is structurally related but lacks the query's second carboxylate and basic amine, leaving quantitative uncertainty in how much its high-F phenotype transfers."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

